      "fullUrl": "https://example.org/fhir/Observation/observation-5",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-5",
        "status": "final",
        "code": {
          "text": "General appearance and gait"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Well-looking, no acute distress at rest. Mild antalgic gait favouring the right, especially for the first few steps; guarded on the right but stable."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-6",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-6",
        "status": "final",
        "code": {
          "text": "Lumbar spine and straight-leg raise examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Lumbar spine non-tender with full range of motion and mild discomfort at extremes. Straight-leg raise negative bilaterally."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Right hip examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No erythema, swelling, or deformity. Marked deep femoral triangle/iliopsoas-region tenderness just distal to the inguinal ligament. No greater trochanter or lateral hip tenderness and no inguinal lymphadenopathy. Flexion limited by pain to approximately 90–100 degrees, with pain on active and passive movement. Internal rotation mildly limited with discomfort; external rotation and extension nearly full, with mild pain at extremes. Resisted hip flexion painful with positive psoas sign. FABER causes mild groin pain; no SIJ pain."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Left hip examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Full range of motion; non-tender."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Lower-limb neurological examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Power 5/5 throughout. Patellar and ankle reflexes present and symmetrical. Light-touch and pinprick sensation intact, including anterior thigh and medial leg. No foot drop."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Abdominal examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Abdomen soft and non-tender, with no masses, organomegaly, or flank tenderness."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-1",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-1",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Unspecified over-the-counter analgesia; patient unsure of product, possibly Panadol or Nurofen"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "As needed; product, dose, route, and frequency details unclear. Patient describes the tablets as 'little white ones or the red ones.'",
            "asNeededBoolean": true
          }
        ]
      }
    }
  ]
}

